def write_images(folder):
    """Writes the test pictures into folder/ and returns that path."""
    folder = pathlib.Path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    for name, data in IMAGES.items():
        (folder / name).write_bytes(base64.b64decode(''.join(data)))
    return folder
